import numpy as np, wave
w=wave.open('/workspace/render_full.wav','rb'); x=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float)/32768
sr=w.getframerate()
PATLEN={0:32,1:64,2:64,3:64,4:64,5:32}
off={}; acc=0
for p in range(6): off[p]=acc; acc+=PATLEN[p]
def chordpeaks(pat,cs):
    # window over chord rows cs..cs+16, middle 1.0s
    t0=(off[pat]+cs+2)*0.09615
    seg=x[int(t0*sr):int((t0+0.9)*sr)]
    Y=np.fft.rfft(seg*np.hanning(len(seg))); f=np.fft.rfftfreq(len(seg),1/sr)
    mag=np.abs(Y)
    return Y,f,mag
def atfreq(Y,f,mag,target):
    i=np.argmin(np.abs(f-target))
    return float(mag[i])
